var body=UnityEngine.SceneManagement.SceneManager.GetActiveScene().GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<UnityEngine.SkinnedMeshRenderer>(true)).First(r=>r.name=="Body"&&r.sharedMaterials.Any(m=>m!=null&&m.shader.name.Contains("MToon")));var go=new UnityEngine.GameObject("Gronny clothing review"){hideFlags=UnityEngine.HideFlags.HideAndDontSave};var camera=go.AddComponent<UnityEngine.Camera>();camera.enabled=false;camera.nearClipPlane=0.03f;camera.farClipPlane=100;camera.fieldOfView=45;var centre=body.bounds.center+UnityEngine.Vector3.up*0.22f;camera.transform.position=centre+new UnityEngine.Vector3(0,0,-1.45f);camera.transform.LookAt(centre);var rt=new UnityEngine.RenderTexture(1000,900,24);var texture=new UnityEngine.Texture2D(1000,900,UnityEngine.TextureFormat.RGB24,false);var previous=UnityEngine.RenderTexture.active;try{camera.targetTexture=rt;camera.Render();UnityEngine.RenderTexture.active=rt;texture.ReadPixels(new UnityEngine.Rect(0,0,1000,900),0,0);texture.Apply();System.IO.File.WriteAllBytes("Docs/Validation/GronnySoftClothing.png",texture.EncodeToPNG());}finally{UnityEngine.RenderTexture.active=previous;camera.targetTexture=null;UnityEngine.Object.DestroyImmediate(go);UnityEngine.Object.DestroyImmediate(texture);UnityEngine.Object.DestroyImmediate(rt);}return new{errors=body.sharedMaterials.Where(m=>m!=null).Select(m=>m.shader).Distinct().SelectMany(UnityEditor.ShaderUtil.GetShaderMessages).Where(m=>m.severity.ToString()=="Error").Select(m=>m.message).ToArray(),capture="Docs/Validation/GronnySoftClothing.png"};
